// 题目 AI 后处理（富化）后台的类型定义。
// 字段与后端 foundation-model / foundation-service 的 JSON tag 一一对应。

// 富化状态机 status（problem_enrich_state）
export enum EnrichStateStatus {
  Init = 0, // 未处理
  Queued = 1, // 排队
  Running = 2, // 处理中
  Success = 3, // 成功
  Failed = 4, // 失败（重试超上限终态）
}

export interface ProblemEnrichState {
  problem_id: number;
  status: EnrichStateStatus;
  stage?: string;
  fingerprint: string;
  attempt: number;
  message?: string;
  worker?: string;
  manual_pending?: boolean; // 手动试运行标记：人工单独重判的题
  insert_time: string;
  modify_time: string;
}

// 后台状态列表行：状态 + 题目定位 + 公开产出 + 流水线进度
export interface EnrichStateItem extends ProblemEnrichState {
  problem_key: string;
  problem_title: string;
  difficulty: number; // 公开综合难度档 1~5，0 未标注
  difficulty_name: string;
  tag_names: string[]; // 正式标签名（最多 4 个）
  summary_line: string; // 摘要一句话（截断）
  steps: EnrichStageStep[]; // 五阶段完成情况
}

// 标签生命周期 status（tag）
export enum TagStatus {
  Candidate = 0, // 候选
  Active = 1, // 正式
  Merged = 2, // 已合并
  Deprecated = 3, // 已归档
}

export interface EnrichTag {
  id: number;
  name: string;
  status: TagStatus;
  merged_to_id?: number;
  source: string; // human / ai
  usage_count: number;
}

export interface TagAlias {
  id: number;
  alias: string;
  tag_id: number;
  inserter: number;
  insert_time: string;
}

// 标签挂载的题目（候选词审查上下文）
export interface TagProblemItem {
  id: number;
  key: string;
  title: string;
}

// 疑似重复标签对（归一化名相似度巡检）
export interface TagSimilarPair {
  left_id: number;
  left_name: string;
  right_id: number;
  right_name: string;
  similarity: number; // 0~1
  left_usage: number;
  right_usage: number;
}

// 标注审核状态
export type ReviewStatus = "" | "pending" | "approved" | "rejected";

// 各 task_type 的 payload（与后端 jsonb 结构一致）
export interface EnrichSummaryPayload {
  oneliner: string;
  io_points: string;
  scale: string;
}

// 公开难度（题目详情页展示：综合档 + 四维）
export interface EnrichPublicDifficulty {
  overall: number;
  grade_name: string;
  thinking: number;
  algorithm: number;
  implementation: number;
  pitfalls: number;
}

export interface EnrichDifficultyPayload {
  overall: number;
  thinking: number;
  algorithm: number;
  implementation: number;
  pitfalls: number;
  evidence: {
    thinking: string;
    algorithm: string;
    implementation: string;
    pitfalls: string;
  };
  cf_rating?: number;
}

export interface EnrichQualityPayload {
  overall: number;
  completeness: number;
  examples: number;
  judge_config: number;
  data_strength: number;
  sources: {
    completeness: string;
    examples: string;
    judge_config: string;
    data_strength: string;
  };
  evidence: Record<string, string>;
}

export interface EnrichSuggestion {
  dimension: string;
  severity: string; // info / warn / block
  evidence: string;
  suggestion: string;
  status: string; // open / done / ignored
}

export interface EnrichSuggestionPayload {
  items: EnrichSuggestion[];
}

export interface EnrichTagsPayload {
  raw: string[];
  canonical: string[];
  candidate: string[];
}

// 审核队列一行（EnrichReviewItem）
export interface EnrichReviewItem {
  id: number;
  problem_id: number;
  task_type: string;
  model: string;
  prompt_ver: string;
  schema_ver: string;
  confidence: number;
  payload: Record<string, unknown>;
  raw_response?: string;
  visibility: string;
  source: string;
  golden: boolean;
  review_status: ReviewStatus;
  reviewer_id?: number;
  review_note?: string;
  review_time?: string;
  insert_time: string;
  problem_key?: string; // 供跳转富化详情页（path 路由用 key）
  problem_title: string;
  problem_statement?: string; // 题面截断（约 600 字），审核卡片内嵌预览
}

// 黄金集一致率报告
export interface EnrichConsistencyItem {
  problem_id: number;
  task_type: string;
  golden: number;
  latest_ai: number; // -1 表示缺失
  exact_match: boolean;
  within_one: boolean;
}

export interface EnrichConsistencyReport {
  task_type: string;
  golden_total: number;
  comparable: number;
  missing: number;
  exact_match: number;
  within_one: number;
  exact_rate: number;
  within_one_rate: number;
  threshold: number;
  passed: boolean;
  details: EnrichConsistencyItem[];
}

// worker 运行配置（judge 每轮 tick 写入 kv_store 的心跳，web 读取展示）。
// judge 未部署/未跑过时后端只返回 { Tier: "judge" }。
export interface EnrichWorkerConfig {
  Tier?: string;
  enabled?: boolean;
  dry_run?: boolean;
  model?: string;
  tier?: string;
  interval_seconds?: number;
  batch_size?: number;
  max_attempt?: number;
  stale_timeout_seconds?: number;
  daily_token_limit?: number;
  daily_problem_limit?: number;
  candidate_promote_usage?: number;
  heartbeat_time?: string; // RFC3339
}

export interface EnrichPage<T> {
  list: T[];
  total: number;
}

// ── 运维总览仪表盘 ──

export interface EnrichCallsDay {
  total: number;
  success: number;
  fail: number;
  running: number;
  success_tokens: number;
  success_cached_tokens?: number; // 成功调用中输入缓存命中部分
  success_rate: number;
}

export interface RunningWorkerStat {
  worker: string;
  count: number;
  oldest_modify: string;
  newest_modify: string;
}

export interface StageLatency {
  stage: string;
  count: number;
  avg_ms: number;
  max_ms: number;
}

// 单题流水线某阶段完成状态
export interface EnrichStageStep {
  stage: string; // summary / tags / difficulty / quality / suggestion
  status: string; // success / fail / running / pending
}

// 总览「当前活动」面板的一行
export interface EnrichActiveProblem {
  problem_id: number;
  problem_key: string;
  problem_title: string;
  stage: string;
  worker: string;
  attempt: number;
  modify_time: string;
  steps: EnrichStageStep[];
}

// 总览「最近失败」面板的一行
export interface EnrichFailureItem {
  problem_id: number;
  problem_key: string;
  problem_title: string;
  message: string;
  modify_time: string;
}

export interface EnrichBudget {
  token_limit: number; // 0 不限制
  token_used: number;
  problem_limit: number;
  problem_used: number;
}

export interface EnrichProgress {
  human_curated: number;
  finished: number;
  pending_total: number;
  today_problems: number;
  rate_per_hour: number;
  eta_minutes: number; // -1 无法估算
}

export interface EnrichWorkerStatus {
  alive: boolean;
  heartbeat_time: string; // 无心跳为空串
  interval_seconds: number;
  stale_timeout_sec: number;
}

export interface EnrichOverview {
  problem_total: number;
  init: number;
  queued: number;
  running: number;
  success: number;
  failed: number;
  coverage_rate: number;
  progress: EnrichProgress;
  today: EnrichCallsDay;
  budget: EnrichBudget;
  worker: EnrichWorkerStatus;
  workers: RunningWorkerStat[];
  stale_workers: string[];
  active: EnrichActiveProblem[];
  recent_failures: EnrichFailureItem[];
  stage_latency: StageLatency[];
  auto_consume: boolean; // false=手动试运行（只跑人工单独重判题），true=全量自动
}

// ── 单题产出详情（只读视图） ──

export interface EnrichDetailHistory {
  id: number;
  source: string;
  golden: boolean;
  review_status: string;
  confidence: number;
  insert_time: string;
  payload: Record<string, unknown>;
}

export interface EnrichDetailAnnotation {
  id: number;
  problem_id: number;
  task_type: string;
  model: string;
  prompt_ver: string;
  schema_ver: string;
  confidence: number;
  payload: Record<string, unknown>;
  raw_response?: string;
  visibility: string;
  source: string;
  golden: boolean;
  review_status: ReviewStatus;
  reviewer_id?: number;
  review_note?: string;
  review_time?: string;
  insert_time: string;
  history: EnrichDetailHistory[]; // 该类型最近历史版本（不含当前行）
}

export interface EnrichProblemDetail {
  problem: CuratorProblem;
  state: ProblemEnrichState | null;
  annotations: EnrichDetailAnnotation[];
  steps: EnrichStageStep[];
  calls: ProblemAnnotationCall[];
}

// 单次 LLM 调用账本
export interface ProblemAnnotationCall {
  id: number;
  problem_id: number;
  annotation_id: number;
  stage: string;
  model: string;
  attempt: number;
  prompt_tokens: number;
  cached_tokens: number; // 输入中命中厂商上下文缓存的部分（计费折扣）
  completion_tokens: number;
  total_tokens: number;
  status: string; // running / success / fail
  duration_ms: number;
  error?: string;
  insert_time: string;
}

export interface EnrichCallItem extends ProblemAnnotationCall {
  problem_key: string;
  problem_title: string;
}

// ── 人工校正 / 人工标注 ──

export interface CuratorProblem {
  id: number;
  key: string;
  title: string;
  time_limit: number;
  memory_limit: number;
  judge_type: number;
  description: string;
  tag_names: string[];
}

export interface CuratorContext {
  problem: CuratorProblem;
  annotations: EnrichReviewItem[];
}

// 人工保存标注请求（annotation_id=0 表示纯人工新建，>0 表示在某条 AI 标注上校正）
export interface SaveHumanAnnotationRequest {
  problem_id: number;
  task_type: string;
  annotation_id: number;
  payload: Record<string, unknown>;
  golden: boolean;
  note: string;
}
